const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '细胞壁' },
      { kind: 'text', payload: '细胞核' },
      { kind: 'text', payload: '液泡' }
    ];
  },
  render: function (input, metrics) {
    var W = (input.viewport && input.viewport.widthDu) || 800;
    var H = (input.viewport && input.viewport.heightDu) || 600;
    var cx = W * 0.50;
    var cy = H * 0.52;
    var rx = W * 0.30;
    var ry = H * 0.31;
    var minDim = Math.min(W, H);

    function ellipsePoints(cx, cy, rx, ry, points, amp, phase) {
      var pts = [];
      for (var i = 0; i <= points; i++) {
        var a = (i / points) * Math.PI * 2;
        var w = 1 + amp * Math.sin(3 * a + phase) + amp * 0.45 * Math.cos(5 * a - 0.4 + phase);
        pts.push([cx + rx * Math.cos(a) * w, cy + ry * Math.sin(a) * w]);
      }
      return pts;
    }
    function organicPointAt(cx, cy, rx, ry, a, amp, phase) {
      var w = 1 + amp * Math.sin(3 * a + phase) + amp * 0.45 * Math.cos(5 * a - 0.4 + phase);
      return [cx + rx * Math.cos(a) * w, cy + ry * Math.sin(a) * w];
    }
    function pointOnCircle(cx, cy, r, px, py) {
      var dx = px - cx;
      var dy = py - cy;
      var len = Math.sqrt(dx * dx + dy * dy) || 1;
      return [cx + dx / len * r, cy + dy / len * r];
    }
    function pointOnEllipse(cx, cy, rx, ry, px, py) {
      var dx = px - cx;
      var dy = py - cy;
      var len = Math.sqrt(dx * dx + dy * dy) || 1;
      var ux = dx / len;
      var uy = dy / len;
      var t = 1 / Math.sqrt((ux / rx) * (ux / rx) + (uy / ry) * (uy / ry));
      return [cx + ux * t, cy + uy * t];
    }
    function textWidth(i, fallback) {
      if (metrics && metrics[i] && typeof metrics[i].width === 'number') return metrics[i].width;
      if (metrics && metrics[i] && metrics[i].metrics && typeof metrics[i].metrics.width === 'number') return metrics[i].metrics.width;
      return fallback;
    }
    function labelStart(label, target, tw) {
      var dx = target[0] - label.x;
      var dy = target[1] - label.y;
      var len = Math.sqrt(dx * dx + dy * dy) || 1;
      var ux = dx / len;
      var uy = dy / len;
      var off = tw / 2 + Math.max(6, minDim * 0.012);
      return [label.x + ux * off, label.y + uy * off];
    }

    var wallLabel = { x: Math.max(minDim * 0.12, cx - rx * 1.02), y: Math.max(minDim * 0.10, cy - ry * 1.25) };
    var nucLabel = { x: Math.max(minDim * 0.12, cx - rx * 1.12), y: Math.min(H - minDim * 0.10, cy + ry * 0.88) };
    var vacLabel = { x: Math.min(W - minDim * 0.12, cx + rx * 1.16), y: Math.max(minDim * 0.10, cy - ry * 0.60) };

    var vx = cx + W * 0.07;
    var vy = cy - H * 0.02;
    var vrx = W * 0.17;
    var vry = H * 0.25;
    var nx = cx - rx * 0.52;
    var ny = cy + ry * 0.30;
    var nr = minDim * 0.070;

    var wallTarget = organicPointAt(cx, cy, rx, ry, Math.PI * 1.17, 0.035, 0.7);
    var nucTarget = pointOnCircle(nx, ny, nr, nucLabel.x, nucLabel.y);
    var vacTarget = pointOnEllipse(vx, vy, vrx, vry, vacLabel.x, vacLabel.y);

    var fallbackTW = Math.max(36, minDim * 0.08);
    var tw0 = textWidth(0, fallbackTW);
    var tw1 = textWidth(1, fallbackTW);
    var tw2 = textWidth(2, fallbackTW);
    var wallStart = labelStart(wallLabel, wallTarget, tw0);
    var nucStart = labelStart(nucLabel, nucTarget, tw1);
    var vacStart = labelStart(vacLabel, vacTarget, tw2);

    var wallCommands = visualSdk.polyline(ellipsePoints(cx, cy, rx, ry, 96, 0.035, 0.7));
    var membraneCommands = visualSdk.polyline(ellipsePoints(cx, cy, rx * 0.91, ry * 0.89, 96, 0.035, 0.7));
    var vacuoleCommands = visualSdk.polyline(ellipsePoints(vx, vy, vrx, vry, 80, 0.008, 0.2));
    var nucleusCommands = visualSdk.circle(nx, ny, nr);
    var nucleolusCommands = visualSdk.circle(nx + nr * 0.18, ny - nr * 0.12, nr * 0.36);
    var lineWallCommands = visualSdk.polyline([wallStart, wallTarget]);
    var lineNucCommands = visualSdk.polyline([nucStart, nucTarget]);
    var lineVacCommands = visualSdk.polyline([vacStart, vacTarget]);
    var dotR = Math.max(2.5, minDim * 0.007);
    var dotWallCommands = visualSdk.circle(wallTarget[0], wallTarget[1], dotR);
    var dotNucCommands = visualSdk.circle(nucTarget[0], nucTarget[1], dotR);
    var dotVacCommands = visualSdk.circle(vacTarget[0], vacTarget[1], dotR);

    var lineWidth = Math.max(1.5, minDim * 0.004);
    var wallStroke = Math.max(2, minDim * 0.005);

    var paths = [
      { id: 'wall', commands: wallCommands },
      { id: 'membrane', commands: membraneCommands },
      { id: 'vacuole', commands: vacuoleCommands },
      { id: 'nucleus', commands: nucleusCommands },
      { id: 'nucleolus', commands: nucleolusCommands },
      { id: 'lineWall', commands: lineWallCommands },
      { id: 'lineNuc', commands: lineNucCommands },
      { id: 'lineVac', commands: lineVacCommands },
      { id: 'dotWall', commands: dotWallCommands },
      { id: 'dotNuc', commands: dotNucCommands },
      { id: 'dotVac', commands: dotVacCommands }
    ];

    var children = [
      { type: 'path', pathId: 'wall', fill: '#cfe0b6', stroke: { width: wallStroke, color: '#6f8f4f' } },
      { type: 'path', pathId: 'membrane', fill: '#f6f9e8', stroke: { width: 2, color: '#9dbb7a' } },
      { type: 'path', pathId: 'vacuole', fill: '#cfe6f2', stroke: { width: 2, color: '#7ea9c8' } },
      { type: 'path', pathId: 'nucleus', fill: '#d7a6c5', stroke: { width: 2, color: '#985c80' } },
      { type: 'path', pathId: 'nucleolus', fill: '#8b4d73', stroke: { width: 1, color: '#7a3f65' } },
      { type: 'path', pathId: 'lineWall', fill: 'none', stroke: { width: lineWidth, color: '#4a6b4f' } },
      { type: 'path', pathId: 'lineNuc', fill: 'none', stroke: { width: lineWidth, color: '#4a6b4f' } },
      { type: 'path', pathId: 'lineVac', fill: 'none', stroke: { width: lineWidth, color: '#4a6b4f' } },
      { type: 'path', pathId: 'dotWall', fill: '#4a6b4f', stroke: { width: 1, color: '#4a6b4f' } },
      { type: 'path', pathId: 'dotNuc', fill: '#4a6b4f', stroke: { width: 1, color: '#4a6b4f' } },
      { type: 'path', pathId: 'dotVac', fill: '#4a6b4f', stroke: { width: 1, color: '#4a6b4f' } },
      { type: 'label', contentId: 'c0', anchor: { x: wallLabel.x, y: wallLabel.y }, hAlign: 'center', vAlign: 'middle', color: '#2f4a32' },
      { type: 'label', contentId: 'c1', anchor: { x: nucLabel.x, y: nucLabel.y }, hAlign: 'center', vAlign: 'middle', color: '#2f4a32' },
      { type: 'label', contentId: 'c2', anchor: { x: vacLabel.x, y: vacLabel.y }, hAlign: 'center', vAlign: 'middle', color: '#2f4a32' }
    ];

    return {
      schemaVersion: 1,
      sceneId: 'plant-cell-diagram',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
